function setUpAboutUsImages() {
  const slideshow = document.querySelector(
    ".widget-1.message .photo-slideshow",
  );
  if (!slideshow) return void console.warn("Slideshow container not found.");
  const waitForPhotos = setInterval(function () {
    const source = document.querySelector(".latest_photos");
    if (!source) return void console.log("Waiting for Latest Photos widget...");
    const images = source.querySelectorAll("li img");
    if (!images.length) return void console.log("Waiting for photo images...");
    const urls = Array.from(images)
      .map(function (img) {
        const match = img.style.backgroundImage.match(
          /url\(["']?(.*?)["']?\)/i,
        );
        return match ? match[1] : null;
      })
      .filter(Boolean);
    if (!urls.length)
      return void console.log("Widget found, but no photo URLs yet...");
    (clearInterval(waitForPhotos),
      console.log("Photo URLs found:", urls),
      (slideshow.innerHTML = ""));
    const slides = urls.map(function (url, index) {
        const img = document.createElement("img");
        return (
          (img.src = url),
          (img.alt = "About Us photo " + (index + 1)),
          0 === index && img.classList.add("active"),
          slideshow.appendChild(img),
          img
        );
      }),
      photos = document.querySelector(".latest_photos"),
      wrapper = document.querySelector(".body_wrapper"),
      parent = photos?.closest(".hp-row");
    if ((parent && wrapper && wrapper.appendChild(parent), slides.length > 1)) {
      let current = 0;
      setInterval(function () {
        (slides[current].classList.remove("active"),
          (current = (current + 1) % slides.length),
          slides[current].classList.add("active"));
      }, 3e3);
    }
  }, 500);
}
function init() {
  (setUpLayout(), setUpAboutUsImages());
}
"loading" !== document.readyState
  ? init()
  : document.addEventListener("DOMContentLoaded", init);
